     1→/**
     2→ * FreeLang Interpreter (Main)
     3→ * Lexer → Parser → Evaluator 파이프라인
     4→ */
     5→
     6→const { Lexer } = require('./lexer');
     7→const { Parser } = require('./parser');
     8→const { Evaluator } = require('./evaluator');
     9→
    10→class FreeLangInterpreter {
    11→  constructor() {
    12→    this.evaluator = new Evaluator();
    13→  }
    14→
    15→  /**
    16→   * 주어진 FreeLang 소스 코드를 실행
    17→   * @param {string} source - FreeLang 소스 코드
    18→   * @returns {*} 프로그램 실행 결과
    19→   */
    20→  execute(source) {
    21→    try {
    22→      // Step 1: Lexical analysis (소스 → 토큰)
    23→      const lexer = new Lexer(source);
    24→      const tokens = lexer.tokenize();
    25→
    26→      // Step 2: Syntax analysis (토큰 → AST)
    27→      const parser = new Parser(tokens);
    28→      const ast = parser.parse();
    29→
    30→      // Step 3: Evaluation (AST → 실행)
    31→      const result = this.evaluator.evaluate(ast);
    32→
    33→      return {
    34→        success: true,
    35→        result: result,
    36→        error: null
    37→      };
    38→    } catch (error) {
    39→      return {
    40→        success: false,
    41→        result: null,
    42→        error: error.message || String(error)
    43→      };
    44→    }
    45→  }
    46→
    47→  /**
    48→   * REPL (Read-Eval-Print-Loop) 모드로 인터프리터 시작
    49→   */
    50→  repl() {
    51→    const readline = require('readline');
    52→    const rl = readline.createInterface({
    53→      input: process.stdin,
    54→      output: process.stdout,
    55→      prompt: 'freeLang> '
    56→    });
    57→
    58→    console.log('FreeLang Interpreter v2.6.0');
    59→    console.log('Type "exit" to quit');
    60→    console.log('---');
    61→
    62→    rl.prompt();
    63→
    64→    rl.on('line', (input) => {
    65→      if (input.toLowerCase() === 'exit') {
    66→        console.log('Goodbye!');
    67→        process.exit(0);
    68→      }
    69→
    70→      if (input.trim()) {
    71→        const result = this.execute(input);
    72→        if (result.success) {
    73→          if (result.result !== null && result.result !== undefined) {
    74→            console.log(result.result);
    75→          }
    76→        } else {
    77→          console.error(`Error: ${result.error}`);
    78→        }
    79→      }
    80→
    81→      rl.prompt();
    82→    });
    83→
    84→    rl.on('close', () => {
    85→      console.log('\nGoodbye!');
    86→      process.exit(0);
    87→    });
    88→  }
    89→
    90→  /**
    91→   * 파일에서 FreeLang 코드를 로드하고 실행
    92→   * @param {string} filePath - .fl 파일 경로
    93→   */
    94→  executeFile(filePath) {
    95→    const fs = require('fs');
    96→    try {
    97→      const source = fs.readFileSync(filePath, 'utf8');
    98→      return this.execute(source);
    99→    } catch (error) {
   100→      return {
   101→        success: false,
   102→        result: null,
   103→        error: `File error: ${error.message}`
   104→      };
   105→    }
   106→  }
   107→}
   108→
   109→module.exports = FreeLangInterpreter;
   110→

