     5→
     6→const runtime = require('./runtime');
     7→const moduleLoader = require('./module-loader');
     8→const {
     9→  Program, VariableDeclaration, FunctionDeclaration, BlockStatement, ExpressionStatement,
    10→  IfStatement, WhileStatement, ForStatement, ForInStatement, ReturnStatement,
    11→  BreakStatement, ContinueStatement, BinaryExpression, UnaryExpression, LogicalExpression,
    12→  CallExpression, MemberExpression, AssignmentExpression, ConditionalExpression,
    13→  ArrayExpression, ObjectExpression, Property, FunctionExpression, Identifier, Literal,
    14→  TryCatchStatement, CatchClause, ThrowStatement, FStringLiteral
    15→} = require('./parser');
    16→
    17→// Control flow signals
    18→const ControlSignal = {
    19→  RETURN: 'return',
    20→  BREAK: 'break',
    21→  CONTINUE: 'continue'
    22→};
    23→
    24→class Environment {
    25→  constructor(parent = null) {
    26→    this.parent = parent;
    27→    this.vars = new Map();
    28→  }
    29→
    30→  define(name, value) {
    31→    this.vars.set(name, value);
    32→  }
    33→
    34→  get(name) {
    35→    if (this.vars.has(name)) {
    36→      return this.vars.get(name);
    37→    }
    38→    if (this.parent) {
    39→      return this.parent.get(name);
    40→    }
    41→    throw new Error(`Undefined variable: ${name}`);
    42→  }
    43→
    44→  set(name, value) {
    45→    if (this.vars.has(name)) {
    46→      this.vars.set(name, value);
    47→      return;
    48→    }
    49→    if (this.parent) {
    50→      this.parent.set(name, value);
    51→      return;
    52→    }
    53→    throw new Error(`Undefined variable: ${name}`);
    54→  }
    55→
    56→  has(name) {
    57→    if (this.vars.has(name)) return true;
    58→    if (this.parent) return this.parent.has(name);
    59→    return false;
    60→  }
    61→}
