    63→class ReturnValue extends Error {
    64→  constructor(value) {
    65→    super();
    66→    this.value = value;
    67→    this.isReturn = true;
    68→  }
    69→}
    70→
    71→class BreakException extends Error {
    72→  constructor() {
    73→    super();
    74→    this.isBreak = true;
    75→  }
    76→}
    77→
