    85→class FreeLangFunction {
    86→  constructor(params, body, closure, name) {
    87→    this.params = params;
    88→    this.body = body;
    89→    this.closure = closure;
    90→    this.name = name || '<anonymous>';
    91→  }
    92→
    93→  call(evaluator, args) {
    94→    const localEnv = new Environment(this.closure);
    95→    for (let i = 0; i < this.params.length; i++) {
    96→      localEnv.define(this.params[i], args[i] || null);
    97→    }
    98→
    99→    try {
   100→      evaluator.executeBlock(this.body.statements || [this.body], localEnv);
   101→      return null;
   102→    } catch (e) {
   103→      if (e.isReturn) {
   104→        return e.value;
   105→      }
   106→      throw e;
   107→    }
   108→  }
   109→
   110→  toString() {
   111→    return `[Function: ${this.name}]`;
   112→  }
   113→}
   114→
   115→class Evaluator {
   116→  constructor() {
   117→    this.globalEnv = new Environment();
   118→    this.currentEnv = this.globalEnv;
   119→
   120→    // Inject built-in functions from runtime
